function.arguments:
{"command":"python3 -c "import pandas as pd;
df = pd.read_csv('outputs/t12_selected_matrix.csv');
indicator_cols = [col for col in df.columns if col not in ['city_id', 'city_name', 'year']]
df_raw = df.copy();
from sklearn.impute import SimpleImputer;
from sklearn.preprocessing import StandardScaler;
from sklearn.cluster import KMeans;
imputer = SimpleImputer(strategy='median');
df_imputed = df.copy();
df_imputed[indicator_cols] = imputer.fit_transform(df[indicator_cols]);
scaler = StandardScaler();
df_scaled = df_imputed.copy();
df_scaled[indicator_cols] = scaler.fit_transform(df_imputed[indicator_cols]);
kmeans = KMeans(n_clusters=3, random_state=0, n_init=10);
clusters = kmeans.fit_predict(df_scaled[indicator_cols]);
df['cluster_id'] = clusters;
df_clusters = df[['city_id', 'city_name', 'year', 'cluster_id']];
df_clusters.to_csv('outputs/t13_city_clusters.csv', index=False);
df_raw['cluster_id'] = clusters;
profile_data = df_raw[['cluster_id'] + indicator_cols];
profiles = profile_data.groupby('cluster_id').mean().reset_index();
profiles = profiles[['cluster_id'] + indicator_cols];
profiles.to_csv('outputs/t13_cluster_profiles.csv', index=False);
print('Check complete.')
"
"}

